WITH candidates AS MATERIALIZED (SELECT j.inbox_id FROM public.wa_campaign_lead_jobs j WHERE j.campaign_id='d8280a2b-4f27-43e0-a8bd-e1e841a302f4' AND j.context->>'historical_authorized'='true' AND j.status IN ('waiting_window','awaiting_category') AND NOT EXISTS (SELECT 1 FROM public.wa_campaign_reply_dispatch d WHERE d.inbox_id=j.inbox_id AND d.status IN ('pending','processing')) ORDER BY j.created_at LIMIT 20), removed AS (DELETE FROM public.wa_campaign_reply_dispatch d USING candidates c WHERE d.inbox_id=c.inbox_id AND d.status IN ('done','failed') RETURNING d.inbox_id) INSERT INTO public.wa_campaign_reply_dispatch(inbox_id) SELECT inbox_id FROM candidates WHERE (SELECT count(*) FROM removed)>=0 ON CONFLICT(inbox_id) DO NOTHING;